import { 금액입력Context, 금액확인Context } from '~/widgets/exchange-payment-funnel/model/schemas';
import { payToFixedQRItem } from '~/entities/pin/api/dtos/schemas';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { DEFAULT_TOKEN_ID } from '~/entities/user/lib/transform-user-with-token-list';
import { CommandType, SuperAppCommandInbound, TrnscTypeCd } from '~/shared/api/dtos/enums';
import { openWebview } from '~/shared/api/web-view';
import { PathType, PATHS } from '~/shared/routes/paths';

type PaymentParams = {
  aliasNm?: string;
  walletInsttCd?: string;
  trnscAmt?: string;
  placeNm?: string;
  placeId?: string;
  trnscId?: string;
  orderNo?: string;
  txCd?: string;
  isAppToApp?: boolean;
  isQrScan?: boolean;
  mpmType?: string;
};

export type ExchangeNavigationParams = PaymentParams & {
  path?: PathType;
  item?: TokenItem;
  payItem?: payToFixedQRItem;
  trnscTypeCd: TrnscTypeCd;
  command?: CommandType;
  tbPayMastr?: any;
  param?: any;
};

export const useExchangeNavigation = () => {
  const navigateToExchange = async ({
    path,
    item,
    trnscTypeCd,
    tbPayMastr,
    command = SuperAppCommandInbound.앱to앱_결제요청,
    param,
    ...args
  }: ExchangeNavigationParams) => {
    if (tbPayMastr) {
      const navigationParams: 금액확인Context = {
        command,
        mpmType: args.mpmType || '',
        tokenId: DEFAULT_TOKEN_ID,
        aliasNm: args.txCd,
        txCd: args.txCd,
        walletInsttCd: tbPayMastr.toInsttCd,
        trnscAmt: String(tbPayMastr.amt ?? '0'),
        placeNm: args.placeNm ?? tbPayMastr.placeNm ?? '',
        placeId: tbPayMastr.placeId,
        trnscId: tbPayMastr.txCd,
        orderNo: tbPayMastr.orderNo,
        trnscTypeCd,
        isAppToApp: args.isAppToApp ?? false,
        isQrScan: args.isQrScan ?? false,
      };

      openWebview(PATHS.exchange.root, navigationParams);
      return;
    }

    if (item) {
      const params = {
        tokenId: item.id,
        trnscTypeCd,
        mpmType: args.mpmType || '',
        ...param,
        ...args,
      };

      openWebview(path || PATHS.exchange.root, params);
      return;
    }

    throw new Error('Either tbPayMastr or item must be provided');
  };

  const navigateToExchangeUseFixMpm = async ({
    path,
    item,
    trnscTypeCd,
    payItem,
    tbPayMastr,
    command = SuperAppCommandInbound.앱to앱_결제요청,
    param,
    ...args
  }: ExchangeNavigationParams) => {
    // Case 1: Using the payment flow with tbPayMastr
    if (tbPayMastr) {
      const navigationParams: 금액입력Context = {
        command,
        mpmType: args.mpmType || '',
        tokenId: DEFAULT_TOKEN_ID,
        aliasNm: args.aliasNm ?? '',
        walletInsttCd: args.walletInsttCd ?? '',
        trnscAmt: String(tbPayMastr.amt ?? '0'),
        placeNm: args.placeNm ?? tbPayMastr.placeNm ?? '',
        placeId: tbPayMastr.placeId ?? '',
        orderNo: tbPayMastr.orderNo ?? '',
        trnscTypeCd,
        isAppToApp: args.isAppToApp ?? false,
        isQrScan: args.isQrScan ?? false,
      };

      openWebview(PATHS.exchange.root, navigationParams);
      return;
    }

    //Case 3: Using the fixed QR payment flow
    if (payItem) {
      // const navigationParams: 금액입력Context = {
      //   command,
      //   tokenId: DEFAULT_TOKEN_ID,
      //   aliasNm: payItem.aliasNm,
      //   walletInsttCd: payItem.bankCode,
      //   trnscTypeCd,
      //   isAppToApp: args.isAppToApp ?? false,
      //   isQrScan: args.isQrScan ?? false,
      // };
      const params = {
        tokenId: DEFAULT_TOKEN_ID,
        aliasNm: payItem.aliasNm,
        walletInsttCd: payItem.bankCode,
        placeId: payItem.placeId,
        placeNm: payItem.placeNm,
        mpmType: args.mpmType || '',
        trnscTypeCd,
        ...param,
        ...args,
      };

      openWebview(PATHS.exchange.root, params);
      return;
    }

    throw new Error('Either tbPayMastr or item must be provided');
  };

  return { navigateToExchange, navigateToExchangeUseFixMpm };
};
